class HindiNormalizer(BaseNormalizer):
    """Fork of Devanagiri normalizer. With additional changes for Hindi and tts_mode."""

    NUKTA = "\u093c"

    DEFAULT_NUMBER_LANG = "hi"

    TTS = TtsLexicon(
        rupee="रुपये",
        dollar="डॉलर",
        won="कोरियाई वॉन",
        point="पॉइंट",
        https="एच टी टी पी एस कोलन स्लैश स्लैश ",
        http="एच टी टी पी कोलन स्लैश स्लैश ",
        dot="डॉट",
        slash="स्लैश",
        at="एट",
        spell_fraction_digits=True,
    )
    LOWERCASE = "tts"

    def __init__(
        self,
        lang="hi",
        remove_nuktas=False,
        nasals_mode="do_nothing",
        do_normalize_chandras=False,
        do_normalize_vowel_ending=False,
        tts_mode=False,
    ):
        super(HindiNormalizer, self).__init__(
            lang,
            remove_nuktas,
            nasals_mode,
            do_normalize_chandras,
            do_normalize_vowel_ending,
            tts_mode,
        )

    def __call__(self, text):
        # common normalization for Indic scripts
        text = super(HindiNormalizer, self).normalize(text)

        # chandra a replacement for Marathi
        text = text.replace("\u0972", "\u090f")

        # decomposing Nukta based composite characters
        text = text.replace("\u0929", "\u0928" + HindiNormalizer.NUKTA)
        text = text.replace("\u0931", "\u0930" + HindiNormalizer.NUKTA)
        text = text.replace("\u0934", "\u0933" + HindiNormalizer.NUKTA)
        text = text.replace("\u0958", "\u0915" + HindiNormalizer.NUKTA)
        text = text.replace("\u0959", "\u0916" + HindiNormalizer.NUKTA)
